    }

    if (loopButton) {
      loopButton.icon = "loop";
      loopButton.observable = editor.playback.onLoopChanged;
      loopButton.update = function (button) {
        button.children[0].style.fill = this.editor.playback.loop
          ? "#8a2828"
          : "#acacac";
      };
