(function installTextShapeWindingPatch() {
  "use strict";

  if (
    typeof THREE === "undefined" ||
    !THREE.ShapePath ||
    !THREE.ShapePath.prototype ||
    typeof THREE.ShapePath.prototype.toShapes !== "function" ||
    THREE.ShapePath.prototype.__zoidiumTextShapeWindingPatch
